$contract$;
revoke all on function diesduck_private.skill_vault_contract() from public, anon, authenticated;

-- Small strict schema matcher: arrays are string enums, objects are exact fields.
create function diesduck_private.vault_matches(value jsonb, spec jsonb) returns boolean
language plpgsql immutable set search_path = '' as $$
declare k text; v jsonb;
begin
  if jsonb_typeof(spec) = 'array' then
    return coalesce(jsonb_typeof(value) = 'string' and spec @> jsonb_build_array(value), false);
  end if;
  if jsonb_typeof(value) is distinct from 'object' then return false; end if;
  for k in select jsonb_object_keys(value) loop
    if not (spec->'fields' ? k) then return false; end if;
  end loop;
  for k,v in select * from jsonb_each(spec->'fields') loop
    if not (value ? k) and spec->'optional' ? k then continue; end if;
    if not diesduck_private.vault_matches(value->k,v) then return false; end if;
  end loop;
  return true;
end $$;

create function diesduck_private.vault_keys(value jsonb, keys text[]) returns boolean
language sql immutable set search_path = '' as $$
  select case when jsonb_typeof(value) = 'object' then
    value ?& keys and not exists(select 1 from jsonb_object_keys(value) k where not(k = any(keys))) else false end;
$$;

create function diesduck_private.valid_vault_selection(kind text, selection jsonb) returns boolean
language plpgsql immutable set search_path = '' as $$
declare contract jsonb := diesduck_private.skill_vault_contract(); r jsonb; leaf jsonb; branch jsonb;
  branches jsonb; structure jsonb; count_effects integer := 0; normal_count integer := 0;
  ids text[] := '{}'; cancelled boolean := false; conflicting boolean := false; found_row boolean;
begin
  if selection is null or octet_length(selection::text) > 32768 then return false; end if;
  if kind = 'D' then
    return diesduck_private.vault_keys(selection,array['optionId'])
      and diesduck_private.vault_matches(selection->'optionId',contract->'D');
  elsif kind = 'B' then
    return exists(select 1 from jsonb_array_elements(contract->'B') row
      where diesduck_private.vault_matches(selection,row->'schema'));
  elsif kind = 'A' then
    if not diesduck_private.vault_keys(selection,array['triggerId','effects'])
      or jsonb_typeof(selection->'triggerId') is distinct from 'string'
      or selection->>'triggerId' !~ '^(all|exact:[0-6]|(gte|lte):[1-6])$' then return false; end if;
    branches := jsonb_build_array(jsonb_build_object('effects',selection->'effects'));
  elsif kind = 'C' then
    if not diesduck_private.vault_keys(selection,array['mode','structure'])
      or coalesce(selection->>'mode','') not in ('normal','special') then return false; end if;
    structure := selection->'structure';
    if selection->>'mode' = 'special' and structure->>'kind' is distinct from 'flat' then return false; end if;
    if structure->>'kind' = 'flat' then
      if not diesduck_private.vault_keys(structure,array['kind','effects']) then return false; end if;
      branches := jsonb_build_array(structure - 'kind');
    elsif structure->>'kind' = 'random' then
      if not diesduck_private.vault_keys(structure,array['kind','branches']) then return false; end if;
      branches := structure->'branches';
      if jsonb_typeof(branches) is distinct from 'array' then return false; end if;
      if jsonb_array_length(branches) not in (2,3) then return false; end if;
    elsif structure->>'kind' = 'hpCondition' then
      if not diesduck_private.vault_keys(structure,array['kind','thresholdOptionId','branches'])
        or not diesduck_private.vault_matches(structure->'thresholdOptionId',contract->'thresholds')
        or not diesduck_private.vault_keys(structure->'branches',array['met','unmet']) then return false; end if;
      branches := jsonb_build_array(structure->'branches'->'met',structure->'branches'->'unmet');
    else return false; end if;
  else return false; end if;
  for branch in select * from jsonb_array_elements(branches) loop
    if not diesduck_private.vault_keys(branch,array['effects']) or jsonb_typeof(branch->'effects') is distinct from 'array' then return false; end if;
    if jsonb_array_length(branch->'effects') = 0 then return false; end if;
    for leaf in select * from jsonb_array_elements(branch->'effects') loop
      count_effects := count_effects + 1; found_row := false;
      for r in select * from jsonb_array_elements(contract->kind) loop
        if not diesduck_private.vault_matches(leaf,r->'schema') then continue; end if;
        if kind = 'C' and not (r->'modes' ? (selection->>'mode')) then continue; end if;
        if kind = 'A' then
          if r->>'face' is not null and selection->>'triggerId' <> 'exact:'||(r->>'face') then continue; end if;
          if not (r->>'duplicate')::boolean and r->>'id' = any(ids) then return false; end if;
          ids := array_append(ids,r->>'id');
          if r->>'id' <> 'cancel-self-attack' then normal_count := normal_count + 1; end if;
          cancelled := cancelled or (r->>'cancel')::boolean;
          conflicting := conflicting or (r->>'conflict')::boolean;
        end if;
        found_row := true; exit;
      end loop;
      if not found_row then return false; end if;
    end loop;
  end loop;
  return case when kind = 'A' then normal_count between 1 and (contract->>'maxA')::integer and not(cancelled and conflicting)
    else count_effects between 1 and (contract->>'maxC')::integer end;
end $$;

create table diesduck_private.skill_vault_counters (
  game_account_id uuid not null references public.game_accounts(id) on delete cascade,
  skill_type text not null check (skill_type in ('A','B','C','D')),
  next_number bigint not null default 1 check (next_number > 0),
  primary key(game_account_id,skill_type)
);
create table diesduck_private.skill_vault (
  id uuid primary key,
  game_account_id uuid not null references public.game_accounts(id) on delete cascade,
  skill_type text not null check (skill_type in ('A','B','C','D')),
  selection jsonb not null check (jsonb_typeof(selection)='object' and octet_length(selection::text)<=32768),
  skill_name text not null check(char_length(skill_name)<=20),
  ruby text not null check(char_length(ruby)<=50),
  fallback_name text,
  created_at timestamptz not null default now(),
  deleted_at timestamptz,
  check ((skill_name='' and fallback_name is not null) or (skill_name<>'' and fallback_name is null))
);
create index skill_vault_account_type on diesduck_private.skill_vault(game_account_id,skill_type,created_at);
alter table diesduck_private.skill_vault enable row level security;
alter table diesduck_private.skill_vault_counters enable row level security;
revoke all on diesduck_private.skill_vault, diesduck_private.skill_vault_counters from public,anon,authenticated;

create function diesduck_private.vault_require_access(account_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null or account_id is null or not exists (
    select 1 from public.game_account_access a where a.game_account_id=account_id and a.auth_user_id=auth.uid()
  ) then raise exception 'Skill vault access denied' using errcode='42501'; end if;
end $$;

create function public.list_skill_vault(p_game_account_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform diesduck_private.vault_require_access(p_game_account_id);
  return (select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'gameAccountId',v.game_account_id,
    'type',v.skill_type,'selection',v.selection,'name',v.skill_name,'ruby',v.ruby,
    'displayName',coalesce(v.fallback_name,v.skill_name),'createdAt',v.created_at) order by v.created_at,v.id),'[]'::jsonb)
    from diesduck_private.skill_vault v where v.game_account_id=p_game_account_id and v.deleted_at is null);
end $$;

create function public.store_skill_vault(p_game_account_id uuid,p_id uuid,p_type text,p_selection jsonb,p_name text,p_ruby text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare old diesduck_private.skill_vault; n bigint; fallback text;
begin
  perform diesduck_private.vault_require_access(p_game_account_id);
  if p_id is null or p_type is null or p_type not in ('A','B','C','D') or p_name is null or p_ruby is null
    or char_length(p_name)>20 or char_length(p_ruby)>50 then raise exception 'Invalid skill' using errcode='22023'; end if;
  -- Serialize only this vault/type; never update game_accounts or its revision.
  insert into diesduck_private.skill_vault_counters(game_account_id,skill_type) values(p_game_account_id,p_type) on conflict do nothing;
  select next_number into n from diesduck_private.skill_vault_counters where game_account_id=p_game_account_id and skill_type=p_type for update;
  select * into old from diesduck_private.skill_vault where id=p_id;
  if found then
    if old.game_account_id<>p_game_account_id or old.skill_type<>p_type or old.selection is distinct from p_selection
      or old.skill_name<>p_name or old.ruby<>p_ruby or old.deleted_at is not null then
      raise exception 'Operation ID already used' using errcode='22023';
    end if;
    return public.list_skill_vault(p_game_account_id);
  end if;
  if not diesduck_private.valid_vault_selection(p_type,p_selection) then raise exception 'Incomplete or invalid selection' using errcode='22023'; end if;
  if p_name='' then
    fallback := 'スキル'||n::text;
    update diesduck_private.skill_vault_counters set next_number=next_number+1 where game_account_id=p_game_account_id and skill_type=p_type;
  end if;
  insert into diesduck_private.skill_vault(id,game_account_id,skill_type,selection,skill_name,ruby,fallback_name)
    values(p_id,p_game_account_id,p_type,p_selection,p_name,p_ruby,fallback);
  return public.list_skill_vault(p_game_account_id);
end $$;

create function public.delete_skill_vault(p_game_account_id uuid,p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform diesduck_private.vault_require_access(p_game_account_id);
  if p_id is null then raise exception 'ID required' using errcode='22023'; end if;
  -- Retain an ID tombstone to prevent an uncertain old store from resurrecting a deleted entry.
  -- Remove the saved content immediately; only the used operation ID remains.
  update diesduck_private.skill_vault set deleted_at=now(),selection='{}',skill_name='',ruby='',fallback_name=''
    where id=p_id and game_account_id=p_game_account_id and deleted_at is null;
  return public.list_skill_vault(p_game_account_id);
end $$;

revoke all on function diesduck_private.vault_matches(jsonb,jsonb),diesduck_private.vault_keys(jsonb,text[]),
  diesduck_private.valid_vault_selection(text,jsonb),diesduck_private.vault_require_access(uuid) from public,anon,authenticated;
revoke all on function public.list_skill_vault(uuid),public.store_skill_vault(uuid,uuid,text,jsonb,text,text),public.delete_skill_vault(uuid,uuid) from public,anon,authenticated;
grant execute on function public.list_skill_vault(uuid),public.store_skill_vault(uuid,uuid,text,jsonb,text,text),public.delete_skill_vault(uuid,uuid) to authenticated;
commit;
